-- Office step 9: fact_key becomes exactly the 24 keys the pipeline links (POC CL-150, CL-152, CL-153; db/V40, V41,
-- db/V2__seed.sql). Three parts, in this file's order:
--   (1) a PRE-CHECK: the 15 SYSTEM keys CL-150 removed must have no stored fact (expected: 0 rows; any row = STOP);
--   (2) the ARCHIVE of every extracted_fact row naming one of the 37 other keys that leave (the POC archived 963 + 86
--       rows): a psql \copy - run this file with psql -f, and CHANGE THE OUTPUT PATH to the office's archive;
--   (3) the DELETE of those rows, then the upsert of the 24 keys (the covered key's question and versions changed at
--       CL-151) and the deletion of every key the register no longer carries.
-- Case data is deleted here, by Ram's ruling of 2026-10-06, and only after (2). Run before step 10 (the time-limit
-- rows name two new day-count keys) and before step 11 (the links name the keys).

-- (1) pre-check: expected 0 rows
SELECT fk.key, count(ef.id) AS stored_facts
  FROM wdp_ai.fact_key fk LEFT JOIN wdp_ai.extracted_fact ef ON ef.fact_key_id = fk.id
 WHERE fk.key IN ('credit.settledBeforeDispute', 'credit.exists', 'credit.amount', 'credit.date', 'reversal.settledBeforeDispute', 'reversal.exists', 'reversal.amount', 'reversal.date', 'crypto.isNonFiatOrNftPurchase', 'delivery.expectedDateSpecified', 'transaction.carriesCashBack', 'transaction.isAirlineTransaction', 'transaction.isAtmCashDisbursement', 'transaction.isAutomatedFuelDispenser', 'transaction.cardProductType')
 GROUP BY fk.key HAVING count(ef.id) > 0;

-- (2) archive: note the COPY n printed
\copy (SELECT ef.id, ef.dispute_case_id, ef.case_document_id, cd.document_ref, fk.key, ef.status, ef.value, ef.page, ef.quote, ef.read_quality, ef.question_version, ef.contract_version, ef.extraction_prompt_version, ef.retry_prompt_version, ef.provider, ef.model, ef.extracted_at FROM wdp_ai.extracted_fact ef JOIN wdp_ai.fact_key fk ON fk.id = ef.fact_key_id LEFT JOIN wdp_ai.case_document cd ON cd.id = ef.case_document_id WHERE fk.key IN ('cardholder.confirmedResolvedInMerchantRecords', 'service.attendedAtAgreedLocation', 'issuer.describesQualityOfProvidedGoodsOrServices', 'issuer.describesTransactionAsFraudulent', 'issuer.describesComplaintAsFlightNotOperated', 'service.usageEvidencedOnRecord', 'issuer.describesPurchaseBeyondClearingData', 'service.futureServicesAvailable', 'crypto.cardholderComplaintIsPostDeliveryAccessLoss', 'delivery.acknowledgedByCardholder', 'delivery.podAddress', 'delivery.customsHoldingCountryRole', 'delivery.despatchAddress', 'delivery.agreedLocationAddress', 'crypto.deliveredToWalletOnRecord', 'crypto.destinationWalletAddress', 'delivery.podAddressMatchesAgreed', 'crypto.txHashOnRecord', 'crypto.costAtTransactionAmount', 'merchant.certifiesCardholderTookMerchandiseAtSale', 'delivery.podContainsFullAddress', 'airline.flightDeparted', 'return.attemptDate', 'return.attemptedOrCompleted', 'delivery.daysAfterAgreedDate', 'dispute.daysAfterReturnAttempt', 'delivery.status', 'delivery.deliveredDate', 'dispute.reportedDate', 'transaction.processDate', 'transaction.saleDate', 'transaction.amount', 'transaction.disputedAmount', 'transaction.isCardPresent', 'delivery.agreedDeliveryDate', 'service.cancellationDate', 'merchant.isTicketAgencySellingThirdPartyEventTickets') ORDER BY ef.id) TO 'C:\\CHANGE-ME\\extracted-fact-retired-keys-CL-152-153.csv' WITH (FORMAT csv, HEADER true)

BEGIN;

CREATE TABLE IF NOT EXISTS wdp_ai.fact_key_bak_20261006 AS SELECT * FROM wdp_ai.fact_key;

-- (3) delete the archived facts: DELETE n must equal the COPY n above
DELETE FROM wdp_ai.extracted_fact
 WHERE fact_key_id IN (SELECT id FROM wdp_ai.fact_key WHERE key IN ('cardholder.confirmedResolvedInMerchantRecords', 'service.attendedAtAgreedLocation', 'issuer.describesQualityOfProvidedGoodsOrServices', 'issuer.describesTransactionAsFraudulent', 'issuer.describesComplaintAsFlightNotOperated', 'service.usageEvidencedOnRecord', 'issuer.describesPurchaseBeyondClearingData', 'service.futureServicesAvailable', 'crypto.cardholderComplaintIsPostDeliveryAccessLoss', 'delivery.acknowledgedByCardholder', 'delivery.podAddress', 'delivery.customsHoldingCountryRole', 'delivery.despatchAddress', 'delivery.agreedLocationAddress', 'crypto.deliveredToWalletOnRecord', 'crypto.destinationWalletAddress', 'delivery.podAddressMatchesAgreed', 'crypto.txHashOnRecord', 'crypto.costAtTransactionAmount', 'merchant.certifiesCardholderTookMerchandiseAtSale', 'delivery.podContainsFullAddress', 'airline.flightDeparted', 'return.attemptDate', 'return.attemptedOrCompleted', 'delivery.daysAfterAgreedDate', 'dispute.daysAfterReturnAttempt', 'delivery.status', 'delivery.deliveredDate', 'dispute.reportedDate', 'transaction.processDate', 'transaction.saleDate', 'transaction.amount', 'transaction.disputedAmount', 'transaction.isCardPresent', 'delivery.agreedDeliveryDate', 'service.cancellationDate', 'merchant.isTicketAgencySellingThirdPartyEventTickets'));

